using HelpDeskPro.Api.Data; using HelpDeskPro.Api.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace HelpDeskPro.Api.Controllers; [ApiController][Route("api/dashboard")][Authorize]
public class DashboardController:ControllerBase { private readonly AppDbContext db; public DashboardController(AppDbContext db){this.db=db;} [HttpGet] public async Task<IActionResult> Get(){return Ok(new{total=await db.Tickets.CountAsync(),open=await db.Tickets.CountAsync(x=>x.Status==TicketStatus.Open),inProgress=await db.Tickets.CountAsync(x=>x.Status==TicketStatus.InProgress),pending=await db.Tickets.CountAsync(x=>x.Status==TicketStatus.Pending),resolved=await db.Tickets.CountAsync(x=>x.Status==TicketStatus.Resolved||x.Status==TicketStatus.Closed),critical=await db.Tickets.CountAsync(x=>x.Priority==Priority.Critical),users=await db.Users.CountAsync(),departments=await db.Departments.CountAsync(),recent=await db.Tickets.Include(x=>x.CreatedBy).OrderByDescending(x=>x.CreatedAt).Take(6).Select(x=>new{x.Id,x.Title,Status=x.Status.ToString(),Priority=x.Priority.ToString(),x.CreatedAt,CreatedBy=x.CreatedBy.FullName}).ToListAsync()});} }
